export type WorkerStatus = 'active' | 'on_leave' | 'absent' | 'late';

export type WorkerTrade =
  | 'Civil'
  | 'Electrical'
  | 'Steel Fixing'
  | 'Concrete'
  | 'Mechanical'
  | 'Masonry'
  | 'Equipment Operation'
  | 'Plumbing'
  | 'Carpentry'
  | 'Painting';

export type CertStatus = 'valid' | 'expiring' | 'expired';
export type ShiftType = 'Day' | 'Night';
export type WorkerType = 'Employee' | 'Subcontractor';

export interface Certification {
  name: string;
  expiryDate: string;
  status: CertStatus;
}

export interface WeeklyAttendanceDay {
  day: string;
  present: boolean;
  late: boolean;
}

export interface Worker {
  id: string;
  name: string;
  initials: string;
  role: string;
  trade: string;
  type: string;
  projectId: string | null;
  project: string | null;
  phone: string | null;
  email: string | null;
  status: WorkerStatus;
  experienceYears: number;
  shift: string;
  attendancePercent: number;
  lastCheckIn: string | null;
  supervisor: string | null;
  emergencyContact: { name: string; phone: string; relation: string } | null;
  skills: string[];
  certifications: Certification[];
  ppeCompliant: boolean;
  weeklyAttendance: WeeklyAttendanceDay[] | null;
  recentActivity: { action: string; time: string; type: string }[] | null;
}

export interface TradeStats {
  trade: WorkerTrade;
  total: number;
  active: number;
  utilization: number;
  openPositions: number;
  skillLevel: 'Expert' | 'Proficient' | 'Intermediate' | 'Beginner';
  color: string;
}

export interface DailyAttendance {
  date: string;
  present: number;
  late: number;
  absent: number;
  onLeave: number;
}

